#include "stdafx.h"#include "TrendsRemoteClient.h"#include <macros/AutoCloser.h>#include <rsuPaths.h>void KTrendsRemoteClient::LoadPlugins(){  if( m_Plugins[0].pInfo )    return;  LPCSTR pExe = rsuGetExecutionPath();  char szMask[_MAX_PATH] = { 0 };  _makepath_s( szMask, NULL, pExe, "rsuSharedTrend_*", "dll");  WIN32_FIND_DATA find;  KAutoCloser<HANDLE> hFind( FindFirstFile( szMask, &find ),                             FindClose );  if( NULL==hFind || INVALID_HANDLE_VALUE==hFind )    return;  int c = 0;  for( BOOL bResult = TRUE; bResult; bResult = FindNextFile( hFind, &find ) )  {    _makepath_s( szMask, NULL, pExe, find.cFileName, NULL);    strncpy_s( m_Plugins[c].szDllName, find.cFileName, _countof(m_Plugins[c].szDllName)-1 );    m_Plugins[c].hm = LoadLibrary( szMask );    if( m_Plugins[c].hm )    {      m_Plugins[c].pInfo = (tTrendInfoPoint)GetProcAddress( m_Plugins[c].hm, "TrendInfoPoint" );      m_Plugins[c].pEnumObjs = (tEnumIo_Objs)GetProcAddress( m_Plugins[c].hm, "EnumObjs" );      m_Plugins[c].pEnumIOs = (tEnumIo_Objs)GetProcAddress( m_Plugins[c].hm, "EnumIOs" );      if( !m_Plugins[c].pInfo )      {        ZeroMemory( &m_Plugins[c], sizeof(m_Plugins[c]) );        continue;      }      c++;      if( c==_countof(m_Plugins) )      {        ASS( 0 );        break;      }    }  }}